INSERT INTO `books` VALUES (1,'Tô Hoài','GOOD','2026-10-29 23:18:29.455759','Chuyến phiêu lưu trưởng thành của Dế Mèn, một tác phẩm văn học thiếu nhi quen thuộc.','/images/covers/literature.svg',NULL,85000.00,59000.00,'Kim Đồng',12,1,'Dế Mèn phiêu lưu ký',1,1),(2,'Paulo Coelho','LIKE_NEW','2026-10-29 23:18:29.460759','Hành trình đi tìm kho báu và lắng nghe tiếng gọi của trái tim.','/images/covers/literature.svg',NULL,115000.00,79000.00,'Nhã Nam',8,1,'Nhà giả kim',1,2),(3,'Nguyễn Nhật Ánh','GOOD','2026-10-29 23:18:29.463946','Những ký ức tuổi thơ bình dị và ấm áp ở miền quê Việt Nam.','/images/covers/literature.svg',NULL,110000.00,72000.00,'Trẻ',6,1,'Tôi thấy hoa vàng trên cỏ xanh',1,3),(4,'Nguyễn Nhật Ánh','LIKE_NEW','2026-10-29 23:18:29.466951','Một tấm vé trở về thế giới trong trẻo của tuổi thơ.','/images/covers/literature.svg',NULL,100000.00,68000.00,'Trẻ',10,1,'Cho tôi xin một vé đi tuổi thơ',1,1),(5,'Rosie Nguyễn','GOOD','2026-10-29 23:18:29.469950','Gợi mở cách học, cách đi và cách sống chủ động trong những năm tuổi trẻ.','/images/covers/life.svg',NULL,98000.00,65000.00,'Hội Nhà Văn',9,1,'Tuổi trẻ đáng giá bao nhiêu',4,2),(6,'Dale Carnegie','LIKE_NEW','2026-10-29 23:18:29.471951','Các nguyên tắc giao tiếp và xây dựng mối quan hệ tích cực.','/images/covers/life.svg',NULL,120000.00,75000.00,'Tổng hợp TP.HCM',15,1,'Đắc nhân tâm',4,1),(7,'Stephen R. Covey','GOOD','2026-10-29 23:18:29.474916','Phương pháp rèn luyện thói quen để chủ động hơn trong công việc và cuộc sống.','/images/covers/life.svg',NULL,160000.00,99000.00,'Tổng hợp TP.HCM',5,1,'7 thói quen hiệu quả',4,3),(8,'Robert T. Kiyosaki','GOOD','2026-10-29 23:18:29.477944','Góc nhìn nhập môn về tài chính cá nhân và tư duy quản lý tiền bạc.','/images/covers/business.svg',NULL,125000.00,85000.00,'Trẻ',7,1,'Cha giàu cha nghèo',2,2),(9,'Dan Senor, Saul Singer','LIKE_NEW','2026-10-29 23:18:29.481944','Khám phá tinh thần đổi mới và hệ sinh thái khởi nghiệp.','/images/covers/business.svg',NULL,145000.00,98000.00,'Thế Giới',4,1,'Quốc gia khởi nghiệp',2,1),(10,'Daniel Kahneman','GOOD','2026-10-29 23:18:29.484945','Tìm hiểu hai hệ thống tư duy ảnh hưởng đến những quyết định hàng ngày.','/images/covers/business.svg',NULL,185000.00,115000.00,'Thế Giới',6,1,'Tư duy nhanh và chậm',2,3),(11,'Antoine de Saint-Exupéry','LIKE_NEW','2026-10-29 23:18:29.486945','Câu chuyện về tình bạn, lòng yêu thương và cách nhìn thế giới bằng trái tim.','/images/covers/children.svg',NULL,80000.00,54000.00,'Kim Đồng',11,1,'Hoàng tử bé',3,2),(12,'Hector Malot','GOOD','2026-10-29 23:18:29.489945','Cuộc hành trình của cậu bé Rémi đi tìm mái ấm và những người thân yêu.','/images/covers/children.svg',NULL,135000.00,89000.00,'Kim Đồng',5,1,'Không gia đình',3,1),(13,'Jenny Han','GOOD','2026-10-29 23:46:44.000000','Belly has always lived for the summertime, because summer means all her favorite things: swimming, the beach, and the Fischer boys, Conrad and Jeremiah. For as long as she can remember, she\'s shared her summers with the brothers at Cousins Beach. And for as long as she can remember, she\'s been in love with Conrad. Then one summer it seems like he might have feelings for her too -- but so does Jeremiah. As the summer seasons pass, Belly has to choose between two brothers who love her ... and she\'ll have to break one of their hearts.\nNguồn: https://openlibrary.org/works/OL17508740W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7719210-M.jpg',NULL,74000.00,49000.00,NULL,3,1,'The Summer I Turned Pretty Trilogy',1,1),(14,'Alex Michaelides','LIKE_NEW','2026-10-29 23:46:44.000000','Alicia Berenson’s life is seemingly perfect. One evening her husband Gabriel returns home late from a fashion shoot, and Alicia shoots him five times in the face, and then never speaks another word. Alicia’s refusal to talk, or give any kind of explanation, turns a domestic tragedy into something far grander, a mystery that captures the public imagination and casts Alicia into notoriety. The price of her art skyrockets, and she, the silent patient, is hidden away from the tabloids and spotlight at the Grove, a secure forensic unit in North London. Theo Faber is a criminal psychotherapist who has waited a long time for the opportunity to work with Alicia. His determination to get her to talk and unravel the mystery of why she shot her husband takes him down a twisting path into his own motivations–a search for the truth that threatens to consume him.\nNguồn: https://openlibrary.org/works/OL19096402W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/9407338-M.jpg',NULL,80000.00,55000.00,NULL,4,1,'The Silent Patient',1,2),(15,'Tahereh Mafi','FAIR','2026-10-29 23:46:44.000000','Juliette hasn\'t touched anyone in exactly 264 days. The last time she did, it was an accident, but The Reestablishment locked her up for murder. No one knows why Juliette\'s touch is fatal. As long as she doesn\'t hurt anyone else, no one really cares. The world is too busy crumbling to pieces to pay attention to a 17-year-old girl. Diseases are destroying the population, food is hard to find, birds don\'t fly anymore, and the clouds are the wrong color. The Reestablishment said their way was the only way to fix things, so they threw Juliette in a cell. Now so many people are dead that the survivors are whispering war-- and The Reestablishment has changed its mind. Maybe Juliette is more than a tortured soul stuffed into a poisonous body. Maybe she\'s exactly what they need right now. Juliette has to make a choice: Be a weapon. Or be a warrior. In this electrifying debut, Tahereh Mafi presents a world as riveting as The Hunger Games and a superhero story as thrilling as The X-Men. Full of pulse-pounding romance, intoxicating villainy, and high-stakes choices, Shatter Me is a fresh and original dystopian novel—with a paranormal twist—that will leave readers anxiously awaiting its sequel.\nNguồn: https://openlibrary.org/works/OL16014245W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6974992-M.jpg',NULL,86000.00,61000.00,NULL,5,1,'Shatter Me',1,3),(16,'Mary Shelley','GOOD','2026-10-29 23:46:44.000000','*Frankenstein; or, The Modern Prometheus* is an 1818 novel written by English author Mary Shelley. Frankenstein tells the story of Victor Frankenstein, a young scientist who creates a sapient creature in an unorthodox scientific experiment. Shelley started writing the story when she was 18, and the first edition was published anonymously in London on 1 January 1818, when she was 20. Her name first appeared in the second edition, which was published in Paris in 1821.\nNguồn: https://openlibrary.org/works/OL450063W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12356249-M.jpg',NULL,92000.00,67000.00,NULL,6,1,'Frankenstein; or, The Modern Prometheus',1,1),(17,'Oscar Wilde','LIKE_NEW','2026-10-29 23:46:44.000000','**The Picture of Dorian Gray** is a philosophical novel by Irish writer Oscar Wilde. A shorter novella-length version was published in the July 1890 issue of the American periodical *Lippincott’s Monthly Magazine*. The novel-length version was published in April 1891.\r\n\r\n(Source: [Wikipedia](https://en.wikipedia.org/wiki/The_Picture_of_Dorian_Gray))\nNguồn: https://openlibrary.org/works/OL8193416W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14314858-M.jpg',NULL,98000.00,73000.00,NULL,7,1,'The Picture of Dorian Gray',1,2),(18,'Holly Black','FAIR','2026-10-29 23:46:44.000000','**GUARD YOUR MORTAL HEART.**\r\n\r\nJUDE WAS SEVEN WHEN HER PARENTS were murdered and she and her two sisters were stolen away to live in the treacherous High Court of Faerie. Ten years later, Jude wants nothing more than to belong there, despite her mortality. But many of the fey despise humans. Especially Prince Cardan, the youngest and wickedest son of the High King.\r\n\r\nTo win a place at the Court, she must defy him--and face the consequences.\r\n\r\nAs Jude becomes more deeply embroiled in palace intrigues and deceptions, she discovers her own capacity for tricker and bloodshed. But as betrayal threatens to drown the Courts of Faerie in violence, Jude will need to risk her life in a dangerous alliance to save her sisters, and Faerie itself.\r\n\r\nFrom #1 *New York Times* bestselling author Holly Black comes the first book in a stunning new trilogy filled with twists and enchantment, as one girl learns the meaning of true power when she finds herself caught in a web of royal faerie intrigue.\r\n\r\nThis description comes from the publisher. *The Cruel Prince* is the first book of the Folk of the Air trilogy.\nNguồn: https://openlibrary.org/works/OL17850410W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8361789-M.jpg',NULL,104000.00,79000.00,NULL,8,1,'The Cruel Prince',1,3),(19,'Jeff Kinney','GOOD','2026-10-29 23:46:44.000000','Greg Heffley finds thrust into middle school, where undersized weaklings like him share the hallways with much bigger kids who are already shaving. But nothing scares Greg more than the moldy piece of cheese on the blacktop. Can he and his best friend, Rowley Jefferson, make it through the year without getting the Cheese Touch?\nNguồn: https://openlibrary.org/works/OL8483260W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14376136-M.jpg',NULL,110000.00,85000.00,NULL,9,1,'Diary of a Wimpy Kid',1,1),(20,'H. G. Wells','LIKE_NEW','2026-10-29 23:46:44.000000','This book is the story of Griffin, a scientist who creates a serum to render himself invisible, and his descent into madness that follows.\nNguồn: https://openlibrary.org/works/OL52266W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6419199-M.jpg',NULL,116000.00,91000.00,NULL,10,1,'The Invisible Man',1,2),(21,'Colleen Hoover','FAIR','2026-10-29 23:46:44.000000','Lily hasn’t always had it easy, but that’s never stopped her from working hard for the life she wants. She’s come a long way from the small town where she grew up—she graduated from college, moved to Boston, and started her own business. And when she feels a spark with a gorgeous neurosurgeon named Ryle Kincaid, everything in Lily’s life seems too good to be true.\r\n\r\nRyle is assertive, stubborn, maybe even a little arrogant. He’s also sensitive, brilliant, and has a total soft spot for Lily. And the way he looks in scrubs certainly doesn’t hurt. Lily can’t get him out of her head. But Ryle’s complete aversion to relationships is disturbing. Even as Lily finds herself becoming the exception to his “no dating” rule, she can’t help but wonder what made him that way in the first place.\r\n\r\nAs questions about her new relationship overwhelm her, so do thoughts of Atlas Corrigan—her first love and a link to the past she left behind. He was her kindred spirit, her protector. When Atlas suddenly reappears, everything Lily has built with Ryle is threatened.\r\n\r\nWith this bold and deeply personal novel, It Ends With Us is a heart-wrenching story and an unforgettable tale of love that comes at the ultimate price.\nNguồn: https://openlibrary.org/works/OL18020194W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10473609-M.jpg',NULL,122000.00,97000.00,NULL,11,1,'It Ends With Us',1,3),(22,'Lauren Roberts','GOOD','2026-10-29 23:46:44.000000','Only the extraordinary belong in the kingdom of Ilya—the exceptional, the empowered, the Elites.\r\n\r\nThe powers these Elites have possessed for decades were graciously gifted to them by the Plague, though not all were fortunate enough to both survive the sickness and reap the reward. Those born Ordinary are just that—ordinary. And when the king decreed that all Ordinaries be banished in order to preserve his Elite society, lacking an ability suddenly became a crime—making Paedyn Gray a felon by fate and a thief by necessity.\r\n\r\nSurviving in the slums as an Ordinary is no simple task, and Paedyn knows this better than most. Having been trained by her father to be overly observant since she was a child, Paedyn poses as a Psychic in the crowded city, blending in with the Elites as best she can in order to stay alive and out of trouble. Easier said than done.\r\n\r\nWhen Paeydn unsuspectingly saves one of Ilyas princes, she finds herself thrown into the Purging Trials. The brutal competition exists to showcase the Elites’ powers—the very thing Paedyn lacks. If the Trials and the opponents within them don’t kill her, the prince she’s fighting feelings for certainly will if he discovers what she is—completely Ordinary. [Powerless pdf](https://chesserresources.com/doc/powerless-by-lauren-roberts-pdf/)\nNguồn: https://openlibrary.org/works/OL34774028W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14567864-M.jpg',NULL,128000.00,103000.00,NULL,12,1,'Powerless',1,1),(23,'Sheridan Le Fanu','LIKE_NEW','2026-10-29 23:46:44.000000','First published as a serial in The Dark Blue (1871–72), *Carmilla* is narrated by a young woman preyed upon by a female vampire named Carmilla, later revealed to be Mircalla, Countess Karnstein (Carmilla is an anagram of Mircalla). The character is a prototypical example of the lesbian vampire, expressing romantic desires toward the protagonist. The novella notably never acknowledges homosexuality as an antagonistic trait, leaving it subtle and morally ambiguous. The story is often anthologised, and has been adapted many times in film and other media.\nNguồn: https://openlibrary.org/works/OL2895536W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/973851-M.jpg',NULL,134000.00,109000.00,NULL,13,1,'Carmilla',1,2),(24,'Tahereh Mafi','FAIR','2026-10-29 23:46:44.000000','\"Juliette has escaped to Omega Point, the headquarters of the rebel resistance and a safe haven for people with abilities like hers. She is finally free from The Reestablishment and their plans to use her as a weapon, but Warner, her former captor, won\'t let her go without a fight.\"--\r\n\r\nJuliette escapes to a safe haven, where she is free from The Reestablishment and their plans to use her as a weapon, but Warner, her former captor, won\'t let go without a fight. The plot contains profanity and sexual violence. Book #2\nNguồn: https://openlibrary.org/works/OL19963111W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12727567-M.jpg',NULL,140000.00,115000.00,NULL,3,1,'Unravel me',1,3),(25,'H. G. Wells','GOOD','2026-10-29 23:46:44.000000','The Time Traveller, a dreamer obsessed with traveling through time, builds himself a time machine and, much to his surprise, travels over 800,000 years into the future. He lands in the year 802701: the world has been transformed by a society living in apparent harmony and bliss, but as the Traveler stays in the future he discovers a hidden barbaric and depraved subterranean class. Wells\'s transparent commentary on the capitalist society was an instant bestseller and launched the time-travel genre.\nNguồn: https://openlibrary.org/works/OL52267W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/9009316-M.jpg',NULL,146000.00,121000.00,NULL,4,1,'The Time Machine',1,1),(26,'Jenny Han','LIKE_NEW','2026-10-29 23:46:44.000000','This book is fresh fun and exciting. 15 year Belly Conklin is enjoying another summer with the people that she loves in Cousins, a place she\'s been going to since she was a baby! The fishers, Aka Jerimiah and Conrad, are finally grown up, and Belly feels like she can fit in aswell. Belly would be turning 16 this year, as now she feels as if she can fit in with the boys. She thinks the summer will be fun, Hanging out on the beach and Playing with the people she loves, Belly is looking foward to her summer vacation. But that\'s when she finds out that Susannah Fisher is diagnosed with Cancer, which changes everything. Things are different in the Summer house. Her first love, Conrad is different, he\'s distant. While the stay in the house was supposed to be enjoying, they need to focus on things that matter the most. Sussanah. Belly decides that it\'s time she acts like the adult that she is. Choosing between her 2 lovers Jerimiah and Conrad Fisher. Will either of them like her? Because this...Is the Summer I turned Pretty.\nNguồn: https://openlibrary.org/works/OL5819962W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8783502-M.jpg',NULL,152000.00,127000.00,NULL,5,1,'The Summer I Turned Pretty',1,2),(27,'Emily Brontë','FAIR','2026-10-29 23:46:44.000000','Wuthering Heights is an 1847 novel by Emily Brontë, initially published under the pseudonym Ellis Bell. It concerns two families of the landed gentry living on the West Yorkshire moors, the Earnshaws and the Lintons, and their turbulent relationships with Earnshaw\'s adopted son, Heathcliff. The novel was influenced by Romanticism and Gothic fiction.\nNguồn: https://openlibrary.org/works/OL21177W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12818862-M.jpg',NULL,158000.00,133000.00,NULL,6,1,'Wuthering Heights',1,3),(28,'Dean Koontz','GOOD','2026-10-29 23:46:44.000000','Tina Evans has spent a year suffering from incredible heartache since her son Danny\'s tragic death. But now, with her Vegas show about to premiere, Tina can think of no better time for a fresh start. Maybe she can finally move on and put her grief behind her.\r\n\r\nOnly there is a message for Tina, scrawled on the chalkboard in Danny\'s room: NOT DEAD. Two words that send her on a terrifying journey from the bright lights of Las Vegas to the cold shadows of the High Sierras, where she uncovers a terrible secret..\nNguồn: https://openlibrary.org/works/OL257746W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12547107-M.jpg',NULL,164000.00,139000.00,NULL,7,1,'The Eyes of Darkness',1,1),(29,'Lucy Maud Montgomery','LIKE_NEW','2026-10-29 23:46:44.000000','New adventures lie ahead for Anne Shirley as she packs her bags, waves goodbye to childhood, and heads for Redmond College. With her old friend Prissy Grant waiting in the bustling city of Kingsport, and frivolous new pal Philippa Gordon at her side, Anne spreads her wings and discovers life on her own terms, filled with surprises: the joys of sharing a house with her irrepressible friends, her very first sale of a story - and a marriage proposal from the worst fellow imaginable!\nNguồn: https://openlibrary.org/works/OL77748W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14639028-M.jpg',NULL,74000.00,49000.00,NULL,8,1,'Anne of the Island',1,2),(30,'Frances Hodgson Burnett','FAIR','2026-10-29 23:46:44.000000','This is a story about a different kind of princess than one might imagine; a princess that is an orphan - lonely, cold, hungry and abused. Sara Crewe begins life as the beloved, pampered daughter of a rich man. When he dies a pauper, she is thrown on the non-existent mercy of her small-minded, mercenary boarding school mistress. Stripped of all her belongings but for one set of clothes and a doll, Sara becomes a servant of the household. Hated by the schoolmistress for her independent spirit, Sara becomes a pariah in the household, with only a few secretly loyal friends. But through her inner integrity and strength of will, Sara Crewe maintains the deportment, inner nobility and generous spirit of a \"real\" princess.\nNguồn: https://openlibrary.org/works/OL69630W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/2328315-M.jpg',NULL,80000.00,55000.00,NULL,9,1,'A Little Princess',1,3),(31,'Charles Dickens','GOOD','2026-10-29 23:46:44.000000','A reprinting of the 1843 first edition, complete with the original illustrations, is supplemented by over eighty related sketches and annotations on and analyses of the text and historical notes on the writing of \"The Christmas Carol.\"\nNguồn: https://openlibrary.org/works/OL32466W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12875748-M.jpg',NULL,86000.00,61000.00,NULL,10,1,'A Christmas Carol',1,1),(32,'Ursula K. Le Guin','LIKE_NEW','2026-10-29 23:46:44.000000','The first novel of Ursula K. Le Guin\'s must-read Earthsea Cycle. \"The magic of Earthsea is primal; the lessons of Earthsea remain as potent, as wise, and as necessary as anyone could dream.\" (Neil Gaiman)\r\n\r\nGed was the greatest sorcerer in Earthsea, but in his youth he was the reckless Sparrowhawk. In his hunger for power and knowledge, he tampered with long-held secrets and loosed a terrible shadow upon the world.\r\n\r\nThis is the tumultuous tale of his testing, how he mastered the mighty words of power, tamed an ancient dragon, and crossed death\'s threshold to restore the balance.\r\n\r\nWith stories as perennial and universally beloved as The Chronicles of Narnia and The Lord of The Rings—but also unlike anything but themselves—Ursula K. Le Guin’s Earthsea novels are some of the most acclaimed and awarded works in literature. They have received accolades such as the National Book Award, a Newbery Honor, the Nebula Award, and many more honors, commemorating their enduring place in the hearts and minds of readers and the literary world alike.\r\n\r\nJoin the millions of fantasy readers who have explored these lands. As The Guardian put it: \"Ursula Le Guin\'s world of Earthsea is a tangled skein of tiny islands cast on a vast sea. The islands\' names pull at my heart like no others: Roke, Perilane, Osskil .\nNguồn: https://openlibrary.org/works/OL59798W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/13617691-M.jpg',NULL,92000.00,67000.00,NULL,11,1,'A Wizard of Earthsea',1,2),(33,'Simon Sinek','FAIR','2026-10-29 23:46:44.000000','The most important question for any organization There\'s a naturally occurring pattern shared by the people and organizations that achieve the greatest long-term success. From Martin Luther King Jr. to Steve Jobs, from the pioneers of aviation to the founders of Southwest Airlines, the most inspiring leaders think, act, and communicate the exact same way—and it\'s the complete opposite of everyone else.The common thread, according to Simon Sinek, is that they all start with why. This simple question has the power to inspire others to achieve extraordinary things.Any organization can explain what it does; some can explain how; but very few can clearly articulate why. Why do we offer these particular products or services? Why do our customers choose us? Why do our employees stay (or leave)? Once you have those answers, teams get stronger, the mission clicks into place, and the path ahead becomes much clearer.Starting with why is the key to everything from putting a man on the moon to launching the iPod. Drawing on a wide range of fascinating examples, Sinek shows readers how to apply why to their culture, hiring decisions, product development, sales, marketing, and many other challenges. Some naturally think this way, but Sinek proves that anyone can learn how.\nNguồn: https://openlibrary.org/works/OL13806374W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6395237-M.jpg',NULL,98000.00,73000.00,NULL,12,1,'Start with why',2,3),(34,'James Clear','GOOD','2026-10-29 23:46:44.000000','No matter your goals, Atomic Habits offers a proven framework for improving every day. James Clear, one of the world\'s leading experts on habit formation, reveals practical strategies that will teach you exactly how to form good habits, break bad ones, and master the tiny behaviors that lead to remarkable results.\nNguồn: https://openlibrary.org/works/OL17930368W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12539702-M.jpg',NULL,104000.00,79000.00,NULL,13,1,'Atomic Habits',2,1),(35,'Alex Hormozi','LIKE_NEW','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Business, Education.\nNguồn: https://openlibrary.org/works/OL25037516W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/11948182-M.jpg',NULL,110000.00,85000.00,NULL,3,1,'$100M Offers',2,2),(36,'Peter A. Thiel','FAIR','2026-10-29 23:46:44.000000','If you want to build a better future, you must believe in secrets.\r\n\r\nThe great secret of our time is that there are still uncharted frontiers to explore and new inventions to create. In Zero to One , legendary entrepreneur and investor Peter Thiel shows how we can find singular ways to create those new things. \r\n\r\nThiel begins with the contrarian premise that we live in an age of technological stagnation, even if we’re too distracted by shiny mobile devices to notice. Information technology has improved rapidly, but there is no reason why progress should be limited to computers or Silicon Valley. Progress can be achieved in any industry or area of business. It comes from the most important skill that every leader must master: learning to think for yourself.\r\n\r\nDoing what someone else already knows how to do takes the world from 1 to n, adding more of something familiar. But when you do something new, you go from 0 to 1. The next Bill Gates will not build an operating system. The next Larry Page or Sergey Brin won’t make a search engine. Tomorrow’s champions will not win by competing ruthlessly in today’s marketplace. They will escape competition altogether, because their businesses will be unique. \r\n\r\nZero to One presents at once an optimistic view of the future of progress in America and a new way of thinking about innovation: it starts by learning to ask the questions that lead you to find value in unexpected places.\nNguồn: https://openlibrary.org/works/OL17078706W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/9002334-M.jpg',NULL,116000.00,91000.00,NULL,4,1,'Zero to One',2,3),(37,'Mark Douglas','GOOD','2026-10-29 23:46:44.000000','Maximizing the trader’s state of mind is the key to successful results. Conflicts, contradictions and paradoxes in thinking can spell disaster for even a highly motivated, astute and well grounded trader. Mark Douglas, a trader, personal trading coach, and industry consultant since 1982, sends the message that \"thinking strategy\" will profoundly influence a trader’s success rate. Douglas addresses five very specific issues to give traders the insight and understanding about themselves that will make them consistent winners in the market.Trading In The Zone offers specific solutions to the “people factor” of commodity price movement. It uncovers the true culprit for lack of consistency when it comes to stock picking: lack of focus and self-confidence. Through simple exercises, traders will learn how to think in terms of probabilities, and adopt the specific beliefs necessary to developing a winner’s mindset. Along the way, they’ll gain valuable insights into their own entrenched misconceptions about the market.Backed by compelling examples, Trading In The Zone adds a new dimension to getting an edge on the market. Through a better understanding of themselves, as well as of Wall Street’s realities, traders will come to leverage the power of their psyche for unprecedented profitability.\nNguồn: https://openlibrary.org/works/OL4461578W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/460625-M.jpg',NULL,122000.00,97000.00,NULL,5,1,'Trading in the zone',2,1),(38,'Ben Horowitz','LIKE_NEW','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Entrepreneurship, Management, New business enterprises, Success in business, nyt:business-books=2014-04-13, New York Times bestseller, Selbstständiger, Unternehmensgründung.\nNguồn: https://openlibrary.org/works/OL16818208W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7279515-M.jpg',NULL,128000.00,103000.00,NULL,6,1,'The Hard Thing About Hard Things',2,2),(39,'Napoleon Hill','FAIR','2026-10-29 23:46:44.000000','Napoleon Hill\'s quintessential volume _Think and grow rich_, the all-time bestseller in the field of professional success, outlines the laws of success and sets the standard of today\'s motivational thinking.\nNguồn: https://openlibrary.org/works/OL527464W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14542536-M.jpg',NULL,134000.00,109000.00,NULL,7,1,'Think and Grow Rich',2,3),(40,'Brian Tracy','GOOD','2026-10-29 23:46:44.000000','There just isn\'t enough time for everything on our to-do list—and there never will be. Successful people don\'t try to do everything. They learn to focus on the most important tasks and make sure those get done. They eat their frogs.\r\nThere\'s an old saying that if the first thing you do each morning is eat a live frog, you\'ll have the satisfaction of knowing you\'re done with the worst thing you\'ll have to do all day. For Tracy, eating a frog is a metaphor for tackling your most challenging task—but also the one that can have the greatest positive impact on your life. Eat That Frog! — Snapshots shows you how to organize each day so you can zero in on these critical tasks and accomplish them efficiently and effectively.\nNguồn: https://openlibrary.org/works/OL2392324W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/847534-M.jpg',NULL,140000.00,115000.00,NULL,8,1,'Eat That Frog! 21 Great Ways to Stop Procrastinating and Get More Done in Less Time',2,1),(41,'Chris Voss','LIKE_NEW','2026-10-29 23:46:44.000000','\"A negotiation guide from a former FBI Hostage Negotiator\"--\n\n\"Never Split The Difference is a riveting, indispensable handbook of negotiation principles culled and perfected from Chris Voss\'s remarkable career as a hostage negotiator and later as an award-winning teacher in the world\'s most prestigious business schools. From policing the rough streets of Kansas City, Missouri, to becoming the FBI\'s lead international kidnapping negotiator, to teaching negotiation at leading universities, Voss has tested these techniques across the full spectrum of human endeavor and proved their effectiveness. Those who have benefited from these techniques include business clients generating millions in additional profits, MBA students getting better jobs, and even parents dealing with their kids. Never Split The Difference provides a gripping, behind-the-scenes recounting of dramatic scenarios from the gang-infested streets of Haiti to a Brooklyn bank robbery gone horribly wrong, revealing the negotiation strategies that helped Voss and his colleagues succeed where it mattered most: saving lives. As a world-class negotiator, Voss shows you how to use these skills in the workplace and in every other realm of your life. Life is a series of negotiations: whether buying a car, getting a better raise, buying a home, renegotiating rent, or deliberating with your partner, Never Split The Difference gives you the competitive edge in any discussion.\"--Jacket.\nNguồn: https://openlibrary.org/works/OL18819818W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8365942-M.jpg',NULL,146000.00,121000.00,NULL,9,1,'Never Split the Difference',2,2),(42,'Ryan Holiday','FAIR','2026-10-29 23:46:44.000000','*#1 Wall Street Journal Bestseller*\r\n\r\nThe Obstacle is the Way has become a cult classic, beloved by men and women around the world who apply its wisdom to become more successful at whatever they do.\r\n\r\nIts many fans include a former governor and movie star (Arnold Schwarzenegger), a hip hop icon (LL Cool J), an Irish tennis pro (James McGee), an NBC sportscaster (Michele Tafoya), and the coaches and players of winning teams like the New England Patriots, Seattle Seahawks, Chicago Cubs, and University of Texas men’s basketball team.\r\n\r\nThe book draws its inspiration from stoicism, the ancient Greek philosophy of enduring pain or adversity with perseverance and resilience. Stoics focus on the things they can control, let go of everything else, and turn every new obstacle into an opportunity to get better, stronger, tougher. As Marcus Aurelius put it nearly 2000 years ago: “The impediment to action advances action. What stands in the way becomes the way.”\r\n\r\nRyan Holiday shows us how some of the most successful people in history—from John D. Rockefeller to Amelia Earhart to Ulysses S. Grant to Steve Jobs—have applied stoicism to overcome difficult or even impossible situations. Their embrace of these principles ultimately mattered more than their natural intelligence, talents, or luck.\r\n\r\nIf you’re feeling frustrated, demoralized, or stuck in a rut, this book can help you turn your problems into your biggest advantages. And along the way it will inspire you with dozens of true stories of the greats from every age and era.\nNguồn: https://openlibrary.org/works/OL19977665W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14428233-M.jpg',NULL,152000.00,127000.00,NULL,10,1,'The Obstacle is the Way',2,3),(43,'Ann Handley','GOOD','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Marketing, Business communication, Internet marketing, Marketing, management, Business writing, BUSINESS & ECONOMICS / General, BUSINESS & ECONOMICS / Business Communication / General, BUSINESS & ECONOMICS / Marketing / General.\nNguồn: https://openlibrary.org/works/OL19337438W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8449611-M.jpg',NULL,158000.00,133000.00,NULL,11,1,'Everybody Writes',2,1),(44,'Robert D. Hisrich','LIKE_NEW','2026-10-29 23:46:44.000000','where we give id to open document\nNguồn: https://openlibrary.org/works/OL2688120W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8231771-M.jpg',NULL,164000.00,139000.00,NULL,12,1,'Entrepreneurship',2,2),(45,'Cal Newport','FAIR','2026-10-29 23:46:44.000000','One of the most valuable skills in our economy is becoming increasingly rare. If you master this skill, you\'ll achieve extraordinary results.\r\n\r\nDeep work is the ability to focus without distraction on a cognitively demanding task. It\'s a skill that allows you to quickly master complicated information and produce better results in less time. Deep work will make you better at what you do and provide the sense of true fulfillment that comes from craftsmanship. In short, deep work is like a super power in our increasingly competitive twenty-first century economy. And yet, most people have lost the ability to go deep-spending their days instead in a frantic blur of e-mail and social media, not even realizing there\'s a better way.\r\n\r\nIn DEEP WORK, author and professor Cal Newport flips the narrative on impact in a connected age. Instead of arguing distraction is bad, he instead celebrates the power of its opposite. Dividing this book into two parts, he first makes the case that in almost any profession, cultivating a deep work ethic will produce massive benefits. He then presents a rigorous training regimen, presented as a series of four \"rules,\" for transforming your mind and habits to support this skill.\r\n\r\nA mix of cultural criticism and actionable advice, DEEP WORK takes the reader on a journey through memorable stories -- from Carl Jung building a stone tower in the woods to focus his mind, to a social media pioneer buying a round-trip business class ticket to Tokyo to write a book free from distraction in the air -- and no-nonsense advice, such as the claim that most serious professionals should quit social media and that you should practice being bored. DEEP WORK is an indispensable guide to anyone seeking focused success in a distracted world.\nNguồn: https://openlibrary.org/works/OL17713267W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7988607-M.jpg',NULL,74000.00,49000.00,NULL,13,1,'Deep Work',2,3),(46,'Jason Fried','GOOD','2026-10-29 23:46:44.000000','Most business books give you the same old advice: Write a business plan, study the competition, seek investors, yadda yadda. If you\'re looking for a book like that, put this one back on the shelf.Rework shows you a better, faster, easier way to succeed in business. Read it and you\'ll know why plans are actually harmful, why you don\'t need outside investors, and why you\'re better off ignoring the competition. The truth is, you need less than you think. You don\'t need to be a workaholic. You don\'t need to staff up. You don\'t need to waste time on paperwork or meetings. You don\'t even need an office. Those are all just excuses.  What you really need to do is stop talking and start working. This book shows you the way. You\'ll learn how to be more productive, how to get exposure without breaking the bank, and tons more counterintuitive ideas that will inspire and provoke you.With its straightforward language and easy-is-better approach, Rework is the perfect playbook for anyone who\'s ever dreamed of doing it on their own. Hardcore entrepreneurs, small-business owners, people stuck in day jobs they hate, victims of \"downsizing,\" and artists who don\'t want to starve anymore will all find valuable guidance in these pages.From the Hardcover edition.\nNguồn: https://openlibrary.org/works/OL15168112W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6679955-M.jpg',NULL,80000.00,55000.00,NULL,3,1,'Rework',2,1),(47,'P. T. Barnum','LIKE_NEW','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Success, Finance, Nonfiction, Self-Improvement, Success in business, Finance, personal, Income, Commerce.\nNguồn: https://openlibrary.org/works/OL891636W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/756095-M.jpg',NULL,86000.00,61000.00,NULL,4,1,'The art of money getting, or, Golden rules for money getting',2,2),(48,'Collins, James C.','FAIR','2026-10-29 23:46:44.000000','\"If you head a small to mid-sized enterprise or one within a larger firm, here is a remarkable book that can help you build an extraordinary organization capable of long-term health and success.\" \"Beyond Entrepreneurship shows how to turn your business into an entity that \"sustains high performance, rises to the status of role model, and remains great for generations,\" in the words of the authors.\" \"Step by step, Collins and Lazier reveal how to lay a foundation for greatness, while a company is still small and adaptable enough to fully embody the values of its leaders.\" \"Drawing on their many years of first-hand experience working in private industry and serving as business consultants, Collins and Lazier cover all the essential aspects of attaining corporate greatness--supported by dozens of real-life examples of firms as diverse as Mrs. Fields Cookies, Continental Cablevision, and Giro Sport Design.\" \"In Beyond Entrepreneurship they provide tested ideas and methods for developing the most effective leadership style for your personality characteristics ... and developing the 7 key elements of a leadership style to inspire real loyalty and dedication.\" \"Then, they move on to an often overlooked function of leadership: catalyzing a vision. Every great company has at its core a compelling vision. You\'ll discover a clear and useful framework for setting corporate vision--a framework that removes the confusion about this important and elusive topic, yet retains the \"spark\" that\'s an essential quality of a motivating and effective overall vision.\" \"Collins and Lazier also discuss and illustrate the four key principles of setting business strategy, and explain how to resolve critical strategic issues--like whether to lead a market or follow--faced by every small to mid-sized firm.\" \"The authors present a set of concepts and practical suggestions for stimulating creativity and keeping your company innovative as it evolves.\"\n\n\"Finally, they spell out how to translate vision and strategy into effective business tactics, the day-to-day details of producing consistent excellence.\" \"Here is a comprehensive, how-to-do-it blue print for becoming the best in your industry; crafting an entity that\'s highly profitable and respected by people outside its walls.\"--Jacket.\nNguồn: https://openlibrary.org/works/OL3486272W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/3974652-M.jpg',NULL,92000.00,67000.00,NULL,5,1,'Beyond entrepreneurship',2,3),(49,'Daniel H. Pink','GOOD','2026-10-29 23:46:44.000000','From Daniel H. Pink, the author of the groundbreaking bestseller A Whole New Mind, comes his next big idea book: a paradigm-changing examination of what truly motivates us and how to harness that knowledge to find greater satisfaction in our lives and our work.We\'ve been conditioned to think that the best way to motivate ourselves and others is through external rewards like money—the carrot-and-the-stick approach. That\'s a mistake, Daniel H. Pink says in his transformative new book. The key to high performance and satisfaction is intrinsic, internal motivation: the desire to follow your own interests and understand the benefits in them for you. And Pink has discovered thirty years of scientific data that confirm these ideas and show an exciting way forward.As he did in his groundbreaking bestseller A Whole New Mind, Pink lays out the hard science for these surprising insights, describes how people and corporations can embrace such ideas (some of them are already doing it), offers details about how we can master them, and provides concrete examples on how intrinsic motivation works on the job, at home, and in ourselves.This is a book of big ideas that explains how each of us can find the surest pathway to high performance, creativity, and even health and well-being.\nNguồn: https://openlibrary.org/works/OL15016965W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6404786-M.jpg',NULL,98000.00,73000.00,NULL,6,1,'Drive',2,1),(50,'Keith Ferrazzi','LIKE_NEW','2026-10-29 23:46:44.000000','Do you want to get ahead in life? Climb the ladder to personal success? The secret, master networker Keith Ferrazzi claims, is in reaching out to other people. As Ferrazzi discovered early in life, what distinguishes highly successful people from everyone else is the way they use the power of relationships--so that everyone wins.In Never Eat Alone, Ferrazzi lays out the specific steps--and inner mindset--he uses to reach out to connect with the thousands of colleagues, friends, and associates on his Rolodex, people he has helped and who have helped him.The son of a small-town steelworker and a cleaning lady, Ferrazzi first used his remarkable ability to connect with others to pave the way to a scholarship at Yale, a Harvard MBA, and several top executive posts. Not yet out of his thirties, he developed a network of relationships that stretched from Washington\'s corridors of power to Hollywood\'s A-list, leading to him being named one of Crain\'s 40 Under 40 and one of Davos\' Global Leader for Tomorrow.Ferrazzi\'s form of connecting to the world around him is based on generosity, helping friends connect with other friends. Ferrazzi distinguishes genuine relationship-building from the crude, desperate glad-handling usually associated with \"networking.\" He then distills his system of reaching out to people into practical, proven principles. Among them:Don\'t keep score: It\'s never simply about getting what you want. It\'s about getting what you want and making sure that the people who are important to you get what they want, too.\"Ping\" constantly: The Ins and Outs of reaching out to those in your circle of contacts all the time--not just when you need something.Never eat alone: The dynamics of status are the same whether you\'re working at a corporation or attending a society event-- \"invisibility\" is a fate worse than failure. In the course of the book, Ferrazzi outlines the timeless strategies shared by the world\'s most connected individuals, from Katherine Graham to Bill Clinton, Vernon Jordan to the Dalai Lama. Chock full of specific advice on handling rejection, getting past gatekeepers, becoming a \"conference commando,\" and more, Never Eat Alone is destined to take its place alongside How to Win Friends and Influence People as an inspirational classic.\nNguồn: https://openlibrary.org/works/OL15169845W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6802201-M.jpg',NULL,104000.00,79000.00,NULL,7,1,'Never Eat Alone',2,2),(51,'M. J. DeMarco','FAIR','2026-10-29 23:46:44.000000','In The Millionaire Fastlane, MJ DeMarco flips the script on the traditional \"get rich slow\" advice. Instead of grinding 40 hours a week for 40 years and hoping to retire rich, he introduces a radical path to wealth — the Fastlane — where time and money freedom can be achieved much sooner.\r\n\r\nDeMarco challenges the common “Slowlane” mindset: saving obsessively, living frugally, and waiting for retirement. Instead, he advocates building scalable businesses, leveraging the internet, and creating value that serves millions.\r\n\r\nHe breaks down wealth into a formula, introduces the “Five Fastlane Commandments,” and explains how to think like a producer instead of a consumer.\r\n\r\nIf you\'re tired of the 9-to-5 rat race and want a practical, mindset-shifting guide to achieving financial freedom, The Millionaire Fastlane is a no-nonsense, punchy roadmap to building real wealth — fast.\nNguồn: https://openlibrary.org/works/OL26428079W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12393433-M.jpg',NULL,110000.00,85000.00,NULL,8,1,'The Millionaire Fastlane',2,3),(52,'Alan Barker','GOOD','2026-10-29 23:46:44.000000','Improve Your Communication Skills shows how to improve conversations and build rapport with colleagues; hold interviews and staff appraisals; learn the skills of persuasion; give effective presentations; write emails, letters and reports; and write for the web.\nNguồn: https://openlibrary.org/works/OL15184542W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6441309-M.jpg',NULL,116000.00,91000.00,NULL,9,1,'Improve Your Communication Skills',2,1),(53,'Jeff Kinney','FAIR','2026-10-29 23:46:44.000000','The pressure\'s really piling up on Greg Heffley. His mom thinks video games are turning his brain to mush, so she wnats her son to put down the controller and explore his \"creative side\".\r\n\r\nAs if that\'s not scary enough, Halloween is just around the corner and the frights are coming at Greg from every angle.\r\n\r\nWhen he discovers a bag of gummy worms, it sparks an idea. Can Greg get his mom off his back by making a movie.... and will he become rich and famous in the progress? Or will doubling down on this path just double Greg\'s troubles?\nNguồn: https://openlibrary.org/works/OL17603394W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7888937-M.jpg',NULL,128000.00,103000.00,NULL,11,1,'Double Down',3,3),(54,'Antoine de Saint-Exupéry','GOOD','2026-10-29 23:46:44.000000','*Le Petit Prince* est une œuvre de langue française, la plus connue d\'Antoine de Saint-Exupéry. Publié en 1943 à New York simultanément à sa traduction anglaise, c\'est une œuvre poétique et philosophique sous l\'apparence d\'un conte pour enfants.\r\n\r\nTraduit en quatre cent cinquante-sept langues et dialectes, *Le Petit Prince* est le deuxième ouvrage le plus traduit au monde après la Bible.\r\n\r\nLe langage, simple et dépouillé, parce qu\'il est destiné à être compris par des enfants, est en réalité pour le narrateur le véhicule privilégié d\'une conception symbolique de la vie. Chaque chapitre relate une rencontre du petit prince qui laisse celui-ci perplexe, par rapport aux comportements absurdes des « grandes personnes ». Ces différentes rencontres peuvent être lues comme une allégorie.\r\n\r\nLes aquarelles font partie du texte et participent à cette pureté du langage : dépouillement et profondeur sont les qualités maîtresses de l\'œuvre.\r\n\r\nOn peut y lire une invitation de l\'auteur à retrouver l\'enfant en soi, car « toutes les grandes personnes ont d\'abord été des enfants. (Mais peu d\'entre elles s\'en souviennent.) ». L\'ouvrage est dédié à Léon Werth, mais « quand il était petit garçon ».\r\n\r\n(Wikipedia)\nNguồn: https://openlibrary.org/works/OL10263W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10708272-M.jpg',NULL,134000.00,109000.00,NULL,12,1,'Le petit prince',3,1),(55,'L. Frank Baum','LIKE_NEW','2026-10-29 23:46:44.000000','Over a century after its initial publication, The Wonderful Wizard of Oz is still captivating the hearts of countless readers. Come adventure with Dorothy and her three friends: the Scarecrow, the Tin Woodman, and the Cowardly Lion, as they follow the Yellow Brick Road to the Emerald City for an audience with the Great Oz, the mightiest Wizard in the land, and the only one that can return Dorothy to her home in Kansas.\nNguồn: https://openlibrary.org/works/OL18417W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/552443-M.jpg',NULL,140000.00,115000.00,NULL,13,1,'The Wonderful Wizard of Oz',3,2),(56,'Jeff Kinney','FAIR','2026-10-29 23:46:44.000000','It’s Greg’s birthday-and you are invited to the **chaos**.\nNguồn: https://openlibrary.org/works/OL42770100W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/15179458-M.jpg',NULL,146000.00,121000.00,NULL,3,1,'Diary of a Wimpy Kid Party Pooper',3,3),(57,'Alexandra Bracken','GOOD','2026-10-29 23:46:44.000000','When Ruby woke up on her tenth birthday, something about her had changed. Something frightening enough to make her parents lock her in the garage and call the police. Something that got her sent to Thurmond, a brutal government “rehabilitation camp.” She might have survived the mysterious disease that had killed most of America’s children, but she and the others emerged with something far worse: frightening abilities they could not control.\r\n\r\nNow sixteen, Ruby is one of the dangerous ones. When the truth comes out, Ruby barely escapes Thurmond with her life. She is on the run, desperate to find the only safe haven left for kids like her—East River. She joins a group of kids who have escaped their own camp. Liam, their brave leader, is falling hard for Ruby. But no matter how much she aches for him, Ruby can’t risk getting close. Not after what happened to her parents. When they arrive at East River, nothing is as it seems, least of all its mysterious leader. But there are other forces at work, people who will stop at nothing to use Ruby in their fight against the government. Ruby will be faced with a terrible choice, one that may mean giving up her only chance at having a life worth living.\nNguồn: https://openlibrary.org/works/OL16591835W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7262992-M.jpg',NULL,152000.00,127000.00,NULL,4,1,'The Darkest Minds',3,1),(58,'Eleanor Hodgman Porter','LIKE_NEW','2026-10-29 23:46:44.000000','An abridged version of the tale of orphaned, eleven-year-old Pollyanna, who comes to live with austere and wealthy Aunt Polly, bringing happiness to her aunt and other members of the community through her philosophy of gladness. Pollyanna knows the secret to finding a smile -- even when really bad things happen. From the moment she arrives in Beldingsville, she shares her Glad Game with everyone around her. But the person who needs Pollyanna\'s help the most doesn\'t want it. - Publisher.\nNguồn: https://openlibrary.org/works/OL2775807W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/902113-M.jpg',NULL,158000.00,133000.00,NULL,5,1,'Pollyanna',3,2),(59,'Roald Dahl','FAIR','2026-10-29 23:46:44.000000','A young boy and his Norwegian grandmother, who is an expert on witches, together foil a witches\' plot to destroy the world\'s children by turning them into mice.\nNguồn: https://openlibrary.org/works/OL45886W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12374442-M.jpg',NULL,164000.00,139000.00,NULL,6,1,'The Witches',3,3),(60,'Lucy Maud Montgomery','GOOD','2026-10-29 23:46:44.000000','Anne, an eleven-year-old orphan, is sent by mistake to live with a lonely, middle-aged brother and sister on a Prince Edward Island farm and proceeds to make an indelible impression on everyone around her.\nNguồn: https://openlibrary.org/works/OL77746W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14641084-M.jpg',NULL,74000.00,49000.00,NULL,7,1,'Anne of Green Gables',3,1),(61,'Edith Nesbit','LIKE_NEW','2026-10-29 23:46:44.000000','E. Nesbit\'s classic story of how Gerald, Cathy and Jimmy find an enchanted garden and awake a princess from a hundred-year sleep, only to have her immediately made invisible by a magic ring. Her rescue is difficult, funny and sometimes frightening.\nNguồn: https://openlibrary.org/works/OL99541W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6644514-M.jpg',NULL,80000.00,55000.00,NULL,8,1,'The Enchanted Castle',3,2),(62,'Jeff Kinney','FAIR','2026-10-29 23:46:44.000000','Life was better in the old days. Or was it?\r\n\r\nThat’s the question Greg Heffley is asking as his town voluntarily unplugs and goes electronics-free. But modern life has its conveniences, and Greg isn’t cut out for an old-fashioned world.\r\n\r\nWith tension building inside and outside the Heffley home, will Greg find a way to survive? Or is going “old school” just too hard for a kid like Greg?\nNguồn: https://openlibrary.org/works/OL17267509W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8314206-M.jpg',NULL,86000.00,61000.00,NULL,9,1,'Old School',3,3),(63,'L. Frank Baum','GOOD','2026-10-29 23:46:44.000000','Tip and his creation, Jack Pumpkin, run away to Oz, where they save the city after it is captured by girls.\nNguồn: https://openlibrary.org/works/OL18396W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12648656-M.jpg',NULL,92000.00,67000.00,NULL,10,1,'The Marvelous Land of Oz',3,1),(64,'Erin Hunter','LIKE_NEW','2026-10-29 23:46:44.000000','Fire Alone Can Save Our Clan... \r\nThunderClan\'s darkest hour is upon them, as Tigerstar\'s quest for power plunges the forest into terrible danger. In order to save the clans, Firestar must uncover the meaning of a very confusing prophecy from StarClan, \"Four will become two. Lion and tiger will meet in battle, and blood will rule the forest.\" \r\nThe time has come for prophecies to unfold, and for heroes to rise...\r\n\r\n----------\r\n**Books in this arc**\r\n\r\n 1. [Into the Wild][1]\r\n 2. [Fire and Ice][2]\r\n 3. [Forest of Secrets][3]\r\n 4. [Rising Storm][4]\r\n 5. [A Dangerous Path][5]\r\n 6. The Darkest Hour\r\n\r\n  [1]: https://openlibrary.org/works/OL5714317W\r\n  [2]: https://openlibrary.org/works/OL5714289W\r\n  [3]: https://openlibrary.org/works/OL5714292W\r\n  [4]: https://openlibrary.org/works/OL5714301W\r\n  [5]: https://openlibrary.org/works/OL5714284W\r\n\r\n----------\r\n**Arcs in this series**\r\n\r\n 1. The Prophecies Begin\r\n 2. [The New Prophecy][b]\r\n 3. [The Power of Three][c]\r\n 4. [Omen of the Stars][d]\r\n 5. [Dawn of the Clans][e]\r\n 6. [A Vision of Shadows][f]\r\n 7. [The Broken Code][g]\r\n 8. [A Starless Clan][h]\r\n S. [Super Editions][s]\r\n\r\n  [a]: https://openlibrary.org/books/OL9228970M/INTO\r\n  [b]: https://openlibrary.org/books/OL9235572M/Midnight_(Warriors_The_New_Prophecy_Book_1)\r\n  [c]: https://openlibrary.org/books/OL7283723M/The_Sight_(Warriors_Power_of_Three_Book_1)\r\n  [d]: https://openlibrary.org/books/OL24084711M/Warriors_Omen_of_the_Stars_1\r\n  [e]: https://openlibrary.org/books/OL25995097M/Dawn_of_the_Clans\r\n  [f]: https://openlibrary.org/books/OL26884472M/The_apprentice\'s_quest\r\n  [g]: https://openlibrary.org/books/OL27958224M/Warriors_The_Broken_Code_1\r\n  [h]: https://openlibrary.org/books/OL32444897M/River/\r\n  [s]: https://openlibrary.org/books/OL7288445M/Firestar\'s_Quest\nNguồn: https://openlibrary.org/works/OL5714310W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8761300-M.jpg',NULL,98000.00,73000.00,NULL,11,1,'The Darkest Hour',3,2),(65,'Kiera Cass','FAIR','2026-10-29 23:46:44.000000','For thirty-five girls, the Selection is the chance of a lifetime. The opportunity to escape the life laid out for them since birth. To be swept up in a world of glittering gowns and priceless jewels. To live in a palace and compete for the heart of gorgeous Prince Maxon.\r\n\r\nBut for America Singer, being Selected is a nightmare. It means turning her back on her secret love with Aspen, who is a caste below her. Leaving her home to enter a fierce competition for a crown she doesn\'t want. Living in a palace that is constantly threatened by violent rebel attacks.\r\n\r\nThen America meets Prince Maxon. Gradually, she starts to question all the plans she\'s made for herself—and realizes that the life she\'s always dreamed of may not compare to a future she never imagined.\nNguồn: https://openlibrary.org/works/OL16361029W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7101900-M.jpg',NULL,104000.00,79000.00,NULL,12,1,'The Selection (The Selection #1)',3,3),(66,'Mo Willems','GOOD','2026-10-29 23:46:44.000000','Gerald the elephant discovers that there is something worse than a bird on your head-- two birds on your head! Piggie will try to help her best friend.\nNguồn: https://openlibrary.org/works/OL5759992W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6667988-M.jpg',NULL,110000.00,85000.00,NULL,13,1,'There is a bird on your head!',3,1),(67,'Jeff Kinney','LIKE_NEW','2026-10-29 23:46:44.000000','In Dog Days, book 4 of the Diary of a Wimpy Kid series from #1 international bestselling author Jeff Kinney, it\'s summer vacation, the weather\'s great, and all the kids are having fun outside. So where\'s Greg Heffley?\r\n\r\nInside his house, playing video games with the shades drawn.\r\n\r\nGreg, a self-confessed \"indoor person,\" is living out his ultimate summer fantasy: no responsibilities and no rules. But Greg\'s mom has a different vision for an ideal summer . . . one packed with outdoor activities and \"family togetherness.\"\r\n\r\nWhose vision will win out? Or will a new addition to the Heffley family change everything?\nNguồn: https://openlibrary.org/works/OL5682519W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12366143-M.jpg',NULL,116000.00,91000.00,NULL,3,1,'Dog Days',3,2),(68,'Rick Riordan','FAIR','2026-10-29 23:46:44.000000','Twelve-year-old Percy Jackson is on the most dangerous quest of his life.  With the help of a satyr and a daughter of Athena, Percy must journey across the United States to catch a thief who has stolen the original weapon of mass destruction—Zeus’ master bolt.  Along the way, he must face a host of mythological enemies determined to stop him.  Most of all, he must come to terms with a father he has never known, and an Oracle that has warned him of betrayal by a friend.\nNguồn: https://openlibrary.org/works/OL492658W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7239831-M.jpg',NULL,122000.00,97000.00,NULL,4,1,'The Lightning Thief',3,3),(69,'Frances Hodgson Burnett','GOOD','2026-10-29 23:46:44.000000','A ten-year-old orphan comes to live in a lonely house on the Yorkshire moors where she discovers an invalid cousin and the mysteries of a locked garden.\nNguồn: https://openlibrary.org/works/OL69612W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12622062-M.jpg',NULL,128000.00,103000.00,NULL,5,1,'The Secret Garden',3,1),(70,'John Green','LIKE_NEW','2026-10-29 23:46:44.000000','Before. Miles “Pudge” Halter is done with his safe life at home. His whole life has been one big non-event, and his obsession with famous last words has only made him crave “the Great Perhaps” even more (Francois Rabelais, poet). He heads off to the sometimes crazy and anything-but-boring world of Culver Creek Boarding School, and his life becomes the opposite of safe. Because down the hall is Alaska Young. The gorgeous, clever, funny, sexy, self-destructive, screwed up, and utterly fascinating Alaska Young. She is an event unto herself. She pulls Pudge into her world, launches him into the Great Perhaps, and steals his heart. Then. . . .\r\n \r\nAfter. *Nothing is ever the same.*\nNguồn: https://openlibrary.org/works/OL265426W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12614602-M.jpg',NULL,134000.00,109000.00,NULL,6,1,'Looking for Alaska',3,2),(71,'Lemony Snicket','FAIR','2026-10-29 23:46:44.000000','After the sudden death of their parents, the three Baudelaire children must depend on each other and their wits when it turns out that the distant relative who is appointed their guardian is determined to use any means necessary to get their fortune.\nNguồn: https://openlibrary.org/works/OL15104144W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7255974-M.jpg',NULL,140000.00,115000.00,NULL,7,1,'The Bad Beginning',3,3),(72,'Joseph Murphy','GOOD','2026-10-29 23:46:44.000000','Examines the connection between the mental dynamics of thinking in relation to one\'s quality of life while offering simple techniques designed to create new, more innovative thought processes and stimulate creativity, in a revised and expanded edition of the best-selling work.\nNguồn: https://openlibrary.org/works/OL55806W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6553019-M.jpg',NULL,146000.00,121000.00,NULL,8,1,'The Power of Your Subconscious Mind',4,1),(73,'Joseph Nguyen','LIKE_NEW','2026-10-29 23:46:44.000000','Discover the book that has helped more than a million readers finally find relief from emotional suffering. Anxiety. Fear. Overthinking. Self-criticism. Is this painful mental state an unavoidable, hardwired fate for humans? Or can we find lasting peace, regardless of our circumstances? Don\'t Believe Everything You Think offers a radical yet simple idea: that the path to mental relief isn\'t through major behavioral change but through understanding how our mind creates our experience of life in the first place. Through an approach that is at once psychological, philosophical, and practical, Nguyen guides readers to a profound understanding of how destructive thinking patterns form -- and how to break them for good. The result? The ability to become emotionally resilient and free from anxiety at any moment. -- Back cover.\r\n\r\nLearn how to overcome anxiety, self-doubt and self-sabotage without needing to rely on motivation or willpower. In this book, you\'ll discover the root cause of all psychological and emotional suffering and how to achieve freedom of mind to effortlessly create the life you\'ve always wanted to live. Although pain is inevitable, suffering is optional. This book offers a completely new paradigm and understanding of where our human experience comes from, allowing us to end our own suffering and create how we want to feel at any moment. -- [josephnguyen.org](http://josephhguyen.org)\nNguồn: https://openlibrary.org/works/OL28098879W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/15260462-M.jpg',NULL,152000.00,127000.00,NULL,9,1,'Don\'t Believe Everything You Think',4,2),(74,'Jordan B. Peterson','FAIR','2026-10-29 23:46:44.000000','Duplicate of https://openlibrary.org/books/OL27241047M/12_Rules_For_Life_Paperback\nNguồn: https://openlibrary.org/works/OL17837119W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8131760-M.jpg',NULL,158000.00,133000.00,NULL,10,1,'12 Rules for Life',4,3),(75,'Brianna Wiest','GOOD','2026-10-29 23:46:44.000000','This book is about self sabotage. Why we do it, when we do it, and how to stop doing it-for good. Coexisting but conflicting needs create self-sabotaging behaviors. This is why we resist efforts to change, often until they feel completely futile. But by extracting crucial insight from our most damaging habits, building emotional intelligence by better understanding our brains and bodies, releasing past experiences at a cellular level, and learning to act as our highest potential future selves, we can step out of our own way and into our potential. For centuries, the mountain has been used as a metaphor for the big challenges we face, especially ones that seem impossible to overcome. To scale our mountains, we actually have to do the deep internal work of excavating trauma, building resilience, and adjusting how we show up for the climb. In the end, it is not the mountain we master, but ourselves.\nNguồn: https://openlibrary.org/works/OL25436364W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/13838236-M.jpg',NULL,164000.00,139000.00,NULL,11,1,'The Mountain Is You',4,1),(76,'Bianca Sparacino','LIKE_NEW','2026-10-29 23:46:44.000000','A gentle reminder for the days you feel light in this world, and for the days in which the sun rises a little slower. A gentle reminder for when your heart is full of hope and for when you are learning how to heal it. A gentle reminder for when you finally begin to trust in the goodness and for when you need the kind of words that hug your broken pieces back together.\r\n\r\nA gentle reminder for when growth hangs heavy in the air, for when you need to tuck your strength into your bones just to make it to tomorrow. A gentle reminder for when you are balancing the messiness—and the beauty—of what it means to be human, when you are teaching yourself that it is okay to be both happy and sad, that you are real, not perfect.\r\n\r\nA gentle reminder to keep going. A gentle reminder to hope. A gentle reminder for you. Take what you need.\nNguồn: https://openlibrary.org/works/OL25296570W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14424196-M.jpg',NULL,74000.00,49000.00,NULL,12,1,'A Gentle Reminder',4,2),(77,'Brianna Wiest','FAIR','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Self-help techniques.\nNguồn: https://openlibrary.org/works/OL26085514W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/15000579-M.jpg',NULL,80000.00,55000.00,NULL,13,1,'When You\'re Ready, This Is How You Heal',4,3),(78,'Maxwell Maltz','GOOD','2026-10-29 23:46:44.000000','Cybernetics (loosely translated from the Greek): “a helmsman who steers his ship to port.” Psycho-Cybernetics is a term coined by Dr. Maxwell Maltz, which means, “steering your mind to a productive, useful goal so you can reach the greatest port in the world, peace of mind.”\r\n\r\nSince its first publication in 1960, Maltz’s landmark bestseller has inspired and enhanced the lives of more than 30 million readers. In this updated edition, with a new introduction and editorial commentary by Matt Furey, president of the Psycho-Cybernetics Foundation, the original text has been annotated and amplified to make Maltz’s message even more relevant for the contemporary reader.\r\n\r\n“Before the mind can work efficiently, we must develop our perception of the outcomes we expect to reach. Maxwell Maltz calls this Psycho-Cybernetics; when the mind has a defined target it can focus and direct and refocus and redirect until it reaches its intended goal.” —Tony Robbins (from Unlimited Power)\r\n\r\nMaltz was the first researcher and author to explain how the self-image (a term he popularized) has complete control over an individual’s ability to achieve (or fail to achieve) any goal. And he developed techniques for improving and managing self-image—visualization, mental rehearsal, relaxation—which have informed and inspired countless motivational gurus, sports psychologists, and self-help practitioners for more than fifty years.\r\n\r\nThe teachings of Psycho-Cybernetics are timeless because they are based on solid science and provide a prescription for thinking and acting that lead to quantifiable results.\nNguồn: https://openlibrary.org/works/OL99079W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14428293-M.jpg',NULL,86000.00,61000.00,NULL,3,1,'Psycho-cybernetics',4,1),(79,'Brianna Wiest','LIKE_NEW','2026-10-29 23:46:44.000000','> \"101 Essays That Will Change The Way You Think, the global bestseller and social media phenomenon, is a collection of author Brianna Wiest\'s most beloved pieces of writing. Her meditations include why you should pursue purpose over passion, embrace negative thinking, see the wisdom in daily routine, and become aware of the cognitive biases that are creating the way you see your life. Some of these pieces have never been seen; others have been read by millions of people around the world. Regardless, each will leave you thinking: this idea changed my life.\"\nNguồn: https://openlibrary.org/works/OL23746568W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10524689-M.jpg',NULL,92000.00,67000.00,NULL,4,1,'101 Essays That Will Change The Way You Think',4,2),(80,'Marcus Aurelius','FAIR','2026-10-29 23:46:44.000000','Meditations is a collection of personal reflections and notes by the Roman Emperor Marcus Aurelius (reigned 161 to 180 AD), offering a profound look into the philosophy of Stoicism. It was never intended for publication, making it a raw and intimate self-help manual for the emperor during his campaigns and rule. The central theme revolves around living a good, rational, and virtuous life in harmony with nature and the cosmos.\r\nAurelius continually reminds himself that everything in the universe is constantly changing and fleeting, urging the reader to accept the impermanence of life and the inevitability of death. He stresses the importance of focusing on what one can control—namely, their own thoughts and actions—and accepting everything else with tranquility, including the behavior of others and external events. This inner fortress of the mind is the only true source of peace.\r\nThe book emphasizes duty and service to the greater community. As a rational being, one\'s purpose is to act justly and benevolently towards fellow humans. Aurelius encourages practicing humility, rising above petty insults, and viewing difficulties as opportunities for growth and the exercise of virtue. He advocates for an objective, detached perspective on all things, stripping away subjective judgment to see the world as it truly is. Ultimately, Meditations is a powerful, timeless guide on how to face adversity, manage emotions, maintain personal integrity, and find contentment through disciplined, rational self-examination and adherence to virtue.\nNguồn: https://openlibrary.org/works/OL1317211W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/211529-M.jpg',NULL,98000.00,73000.00,NULL,5,1,'Meditations',4,3),(81,'Ichirō Kishimi','GOOD','2026-10-29 23:46:44.000000','*\"The Courage to Be Disliked,* already an enormous bestseller in Asia with more than 3.5 million copies sold, demonstrates how to unlock the power within yourself to be the person you truly want to be. Using the theories of Alfred Adler, one of the three giants of twentieth century psychology, *The Courage to Be Disliked* follows an illuminating conversation between a philosopher and a young man. The philosopher explains to his pupil how each of us is able to determine our own life, free from the shackles of past experiences, doubts, and the expectations of others. It\'s a way of thinking that is deeply liberating, allowing us to develop the courage to change, and to ignore the limitations that we and other people have placed on us. The result is a book that is both highly accessible and profound in its importance. Millions have already read and benefitted from its wisdom. This truly life-changing book will help you declutter your mind of harmful thoughts and attitudes, helping you to make a lasting change, achieve real happiness, and find success\"--\r\n\r\n*\"The Life-Changing Magic of Tidying Up* for the mind, *The Courage to Be Disliked* is the Japanese phenomenon that shows you how to free yourself from the shackles of past experiences and others\' expectations to achieve real happiness\"--\nNguồn: https://openlibrary.org/works/OL19744000W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10873626-M.jpg',NULL,104000.00,79000.00,NULL,6,1,'嫌われる勇気',4,1),(82,'Jen Sincero','LIKE_NEW','2026-10-29 23:46:44.000000','The first ever self-development book to help millions of people around the globe transform their lives using humor, irreverence, and the occasional curse word—now updated and expanded for its 10th anniversary with a brand-new foreword, reader\'s guide, and more!\r\n\r\nIn this refreshingly entertaining guide to reshaping your mindset and your life, mega-bestselling author and world-traveling success coach Jen Sincero serves up 27 bite-sized chapters full of hilarious and inspiring stories, sage advice, loving yet firm kicks in the rear, and easy-to-implement exercises to help you:\r\n\r\nIdentify and change the self-sabotaging beliefs and behaviors that stop you from getting what you want.\r\nShift your energy and attract what you desire.\r\nCreate a life you totally love. And start creating it NOW.\r\nMake some damn money already. The kind you\'ve never made before.\r\nBy the end of You Are a Badass, you’ll understand how to blast past what’s holding you back, make some serious changes, and start living the kind of life that once seemed impossible.\nNguồn: https://openlibrary.org/works/OL17102197W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7436635-M.jpg',NULL,110000.00,85000.00,NULL,7,1,'You Are a Badass',4,2),(83,'Eric Robertson','FAIR','2026-10-29 23:46:44.000000','We oftentimes look towards the outside world to find the roots of our problems. However, most of the times, we should be looking inwards. Our mind and our emotions determine our state of being in the present moment. If those aspects are left unchecked, we can get easily overwhelmed and are left feeling unfulfilled every single day. \r\n\r\nThis book contains two manuscripts designed to help you discover the best and most efficient way to control your thoughts and master your feelings.\r\n\r\nIn the first part of the bundle called Breaking Overthinking, you will discover:\r\n\r\nHow overthinking can be detrimental to your social life. \r\nThe hidden dangers of overthinking and what can happen to you if it’s left untreated. \r\nHow to declutter your mind from all the noise of the modern world. \r\nHow overthinking affects your body, your energy levels, and your everyday mood. \r\nHow your surroundings affect your state of mind, and what you NEED to do in order to break out of that state. \r\nBad habits we perform every day and don’t even realize are destroying our sanity (and how to overcome them properly). \r\nHow to cut out toxic people from your life, which cloud your judgment and make you feel miserable.\nNguồn: https://openlibrary.org/works/OL25312237W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12009823-M.jpg',NULL,116000.00,91000.00,NULL,8,1,'Control Your Mind and Master Your Feelings',4,3),(84,'Joe Navarro','GOOD','2026-10-29 23:46:44.000000','He says that\'s his best offer. Is it? She says she agrees. Does she? The interview went great—or did it? He said he\'d never do it again. But he did.\r\n\r\nRead this book and send your nonverbal intelligence soaring. Joe Navarro, a former FBI counterintelligence officer and a recognized expert on nonverbal behavior, explains how to \"speed-read\" people: decode sentiments and behaviors, avoid hidden pitfalls, and look for deceptive behaviors. You\'ll also learn how your body language can influence what your boss, family, friends, and strangers think of you. You will discover:\r\n\r\n- The ancient survival instincts that drive body language\r\n- Why the face is the least likely place to gauge a person\'s true feelings\r\n- What thumbs, feet, and eyelids reveal about moods and motives\r\n- The most powerful behaviors that reveal our confidence and true sentiments \r\n- Simple nonverbals that instantly establish trust\r\n- Simple nonverbals that instantly communicate authority \r\n\r\nFilled with examples from Navarro\'s professional experience, this definitive book offers a powerful new way to navigate your world.\nNguồn: https://openlibrary.org/works/OL12926505W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8734461-M.jpg',NULL,122000.00,97000.00,NULL,9,1,'What every BODY is saying',4,1),(85,'Joe Dispenza','LIKE_NEW','2026-10-29 23:46:44.000000','Argues that all human beings have the power within them to overcome predisposed beliefs and habits to make significant changes in one\'s life, and provides step-by-step tools to make such changes using understandings between science and spirituality.\nNguồn: https://openlibrary.org/works/OL16215950W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/11348192-M.jpg',NULL,128000.00,103000.00,NULL,10,1,'Breaking the habit of being yourself',4,2),(86,'Smart Reads','FAIR','2026-10-29 23:46:44.000000','Workbook for The Mountain is You: Transforming Self-Sabotage Into Self-Mastery\r\n\r\nDo you wonder or even believe that you are in the way of your own happiness and don’t know how to prevent it?\r\n\r\nDo you know how your negative thoughts and beliefs are holding you back from being your best self?\r\n\r\nAre you aware that your self-sabotaging behavior could be harming your chances of reaching your goals and living your best life?\r\n\r\nIf any of these are true, there\'s an easy solution: learn how to overcome your biggest barrier - yourself.\r\n\r\nThe Mountain Is You unravels the secrets of self-sabotage and teaches you how to overcome it for good! Discover why you resist change and how to break free from damaging habits. Build emotional intelligence, release past experiences, and unlock your highest potential. Explore the metaphor of the mountain and master yourself to conquer life\'s biggest challenges. It\'s time to step into your full potential and achieve the impossible!\r\n\r\nThis condensed workbook not only presents Brianna Wiest\'s life-changing insights but also provides a practical roadmap for applying her methods. With reflective questions, practical exercises, and additional insights, you can deepen your comprehension of the concepts and embark on a journey of self-mastery.\nNguồn: https://openlibrary.org/works/OL31113476W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14426421-M.jpg',NULL,134000.00,109000.00,NULL,11,1,'Workbook for the Mountain Is You',4,3),(87,'Zara Bas','GOOD','2026-10-29 23:46:44.000000','A collection of modern poetic-style prose to cradle, comfort, guide and hold space for emotions big and small. Fans of Brianna Wiest, Bianca Sparacino, and Yung Pueblo are sure to enjoy.\r\n\r\nI Have to Tell You Something is Zara Bas\'s first book of pieces written from the most tender depths of a healing heart exploring themes of love, loss, grief, loneliness and self-worth. Split into two sections of soft and hard truths, these are the words your inner child needed to hear.\nNguồn: https://openlibrary.org/works/OL28110702W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/13945571-M.jpg',NULL,140000.00,115000.00,NULL,12,1,'I Have to Tell You Something',4,1),(88,'Napoleon Hill','LIKE_NEW','2026-10-29 23:46:44.000000','Originally written in 1938 but never published due to its controversial nature, an insightful guide reveals the seven principles of good that will allow anyone to triumph over the obstacles that must be faced in reaching personal goals.\nNguồn: https://openlibrary.org/works/OL16176999W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/8260315-M.jpg',NULL,146000.00,121000.00,NULL,13,1,'Outwitting the devil',4,2),(89,'Nicole Apelian','FAIR','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Medicine, Self-help techniques.\nNguồn: https://openlibrary.org/works/OL26794101W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/15257607-M.jpg',NULL,152000.00,127000.00,NULL,3,1,'Lost Book of Herbal Remedies',4,3),(90,'Martin Meadows','GOOD','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Self-help techniques.\nNguồn: https://openlibrary.org/works/OL22706549W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10489426-M.jpg',NULL,158000.00,133000.00,NULL,4,1,'365 Days with Self-Discipline',4,1),(91,'James Allen','LIKE_NEW','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: New Thought, Conduct of life, Miniature books, Specimens, Inspirational, Body, Mind & Spirit, New Age, Inspirational - General.\nNguồn: https://openlibrary.org/works/OL43024W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6268048-M.jpg',NULL,164000.00,139000.00,NULL,5,1,'As a Man Thinketh',4,2),(92,'Neil Alexander Campbell','FAIR','2026-10-29 23:46:44.000000','A comprehensive text for undergraduate-level biology courses that covers cells, genetics, mechanisms and evolution, biological diversity, plant and animal forms and functions, and ecology; and includes review questions, activities, figures, chapter summaries, and a CD-ROM which provides access to online materials.\nNguồn: https://openlibrary.org/works/OL1983087W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/581911-M.jpg',NULL,74000.00,49000.00,NULL,6,1,'Biology',5,3),(93,'Dan Simmons','GOOD','2026-10-29 23:46:44.000000','On the world called Hyperion, beyond the law of the Hegemony of Man, there waits the creature called the Shrike.  There are those who worship it.  There are those who fear it.  And there are those who have vowed to destroy it.  In the Valley of the Time Tombs, where huge, brooding structures move backward through time, the Shrike waits for them all.  On the eve of Armageddon, with the entire galaxy at war, seven pilgrims set forth on a final voyage to Hyperion seeking the answers to the unsolved riddles of their lives.  Each carries a desperate hope--and a terrible secret.  And one may hold the fate of humanity in his hands.\nNguồn: https://openlibrary.org/works/OL1963251W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/484900-M.jpg',NULL,80000.00,55000.00,NULL,7,1,'The Fall of Hyperion',5,1),(94,'刘慈欣','LIKE_NEW','2026-10-29 23:46:44.000000','Soon to be a Netflix Original Series!\r\n\r\n“The War of the Worlds for the 21st century… packed with a sense of wonder.” – Wall Street Journal\r\n\r\nThe New York Times bestselling conclusion to a tour de force near-future adventure trilogy from China\'s bestselling and beloved science fiction writer.\r\n\r\nWith The Three-Body Problem, English-speaking readers got their first chance to read China\'s most beloved science fiction author, Cixin Liu. The Three-Body Problem was released to great acclaim including coverage in The New York Times and The Wall Street Journal and reading list picks by Barack Obama and Mark Zuckerberg. It was also won the Hugo and Nebula Awards, making it the first translated novel to win a major SF award.\r\n\r\nNow this epic trilogy concludes with Death\'s End. Half a century after the Doomsday Battle, the uneasy balance of Dark Forest Deterrence keeps the Trisolaran invaders at bay. Earth enjoys unprecedented prosperity due to the infusion of Trisolaran knowledge. With human science advancing daily and the Trisolarans adopting Earth culture, it seems that the two civilizations will soon be able to co-exist peacefully as equals without the terrible threat of mutually assured annihilation. But the peace has also made humanity complacent.\r\n\r\nCheng Xin, an aerospace engineer from the early twenty-first century, awakens from hibernation in this new age. She brings with her knowledge of a long-forgotten program dating from the beginning of the Trisolar Crisis, and her very presence may upset the delicate balance between two worlds. Will humanity reach for the stars or die in its cradle?\nNguồn: https://openlibrary.org/works/OL17610507W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/7893958-M.jpg',NULL,86000.00,61000.00,NULL,8,1,'Death\'s End (The Three-Body Problem Series Book 3)',5,2),(95,'Аркадий Стругацкий','FAIR','2026-10-29 23:46:44.000000','[Comment by Hari Kunru in The Guardian][1]:\r\n\r\n> Soviet-era Russian science fiction deserves a wider audience in English. The Strugatsky brothers collaborated on numerous novels and stories, the best known of which is this, partly because it was filmed by Andrei Tarkovsky as Stalker, in 1977. The novel takes place 10 years after a mysterious alien visitation, which seems to have no rational explanation. No one saw the visitors. Their presence caused disease and blindness in the areas where they landed. Now, in the six \"Zones\", the laws of physics (and, seemingly, of reality) are disturbed by anomalies, and littered with inexplicable, deadly wreckage. Only a few brave \"stalkers\" risk their lives to enter the zones to gather alien artefacts for sale. Some of these artefacts offer the promise of extraordinary powers. Unlike Tarkovsky\'s film, which concentrates on the hallucinatory, vacated landscape of the zones, the novels portray a society adapting to an inexplicable, terrifying event, an eruption of the unknown. Though written in 1971 and published in English in 1977, the novel was heavily bowdlerised by Soviet censors, and an authoritative text wasn\'t available in Russian until 2000. It\'s a book with an extraordinary atmosphere – and a demonstration of how science fiction, by using a single bold central metaphor, can open up the possibilities of the novel.\r\n\r\nOriginal Title: Пикник на обочине\r\n\r\n\r\n  [1]: http://www.guardian.co.uk/books/2011/may/14/science-fiction-authors-choice\nNguồn: https://openlibrary.org/works/OL7967812W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6752719-M.jpg',NULL,92000.00,67000.00,NULL,9,1,'Roadside Picnic',5,3),(96,'Isaac Asimov','GOOD','2026-10-29 23:46:44.000000','In the future you will walk down the crowded streets of New York City not knowing if the bodies brushing past you are humans or androids. With tensions already mounting between humans and robots, the murder of a Spacer must be handled in a politically-correct fashion so Detective Elijah Baley is assigned a robot partner.\r\n\r\nBaley and R. Daneel Olivaw become like Sir Arthur Conan Doyle s Sherlock Holmes and Dr. Watson, Law & Order s Detectives Lennie Brisco and Ed Green, and Training Day s Detective Alonzo Harris and Officer Jake Hoyt disparate partners who must work together to solve a crime. The only problem is, Baley doesn\'t trust anyone not his boss, not his wife, and certainly not his robot partner.\nNguồn: https://openlibrary.org/works/OL46401W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/13790511-M.jpg',NULL,98000.00,73000.00,NULL,10,1,'The Caves of Steel',5,1),(97,'Isaac Asimov','LIKE_NEW','2026-10-29 23:46:44.000000','- Foundation\r\n - Foundation and Empire\r\n - Second Foundation\r\n\r\nIsaac Asimov\'s Foundation novels are some of the great masterworks of science fiction. Unsurpassed for their unique blend of nonstop action, daring ideas, and extensive world-building, they chronicle the struggle of a courageous group of men and women working to preserve humanity’s light against an inexorable tide of darkness and violence.\r\n\r\nLed by its founding father, the great psychohistorian Hari Seldon, and taking advantage of its superior science and technology, the Foundation has survived the greed and barbarism of its neighboring warrior-planets. Yet now it must face the Empire—still the mightiest force in the Galaxy even in its death throes. When an ambitious general determined to restore the Empire’s glory turns the vast imperial fleet toward the Foundation, the only hope for the small planet of scholars and scientists lies in the prophecies of Hari Seldon.\r\n\r\nBut not even Hari Seldon could have predicted the birth of the extraordinary creature called The Mule, a mutant intelligence with a power greater than a dozen battle fleets… a power that can turn the strongest-willed human into an obedient slave.\nNguồn: https://openlibrary.org/works/OL46390W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6502517-M.jpg',NULL,104000.00,79000.00,NULL,11,1,'The Foundation Trilogy',5,2),(98,'Isaac Asimov','FAIR','2026-10-29 23:46:44.000000','These two renowned writers have invented a world not unlike our own--a world on the edge of chaos, torn between the madness of religious fanaticism and the stubborn denial of scientists. Only a handful of people on the planet Lagash are prepared to face the truth--that their six suns are setting all at once for the first time in 2,000 years, signaling the end of civilization!\nNguồn: https://openlibrary.org/works/OL46374W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/9302081-M.jpg',NULL,110000.00,85000.00,NULL,12,1,'Nightfall',5,3),(99,'刘慈欣','GOOD','2026-10-29 23:46:44.000000','Soon to be a Netflix Original Series!\r\n\r\n\"Wildly imaginative.\" —President Barack Obama on The Three-Body Problem trilogy\r\n\r\nThis near-future trilogy is the first chance for English-speaking readers to experience this multiple-award-winning phenomenon from Cixin Liu, China\'s most beloved science fiction author.\r\n\r\nIn The Dark Forest, Earth is reeling from the revelation of a coming alien invasion-in just four centuries\' time. The aliens\' human collaborators may have been defeated, but the presence of the sophons, the subatomic particles that allow Trisolaris instant access to all human information, means that Earth\'s defense plans are totally exposed to the enemy. Only the human mind remains a secret. This is the motivation for the Wallfacer Project, a daring plan that grants four men enormous resources to design secret strategies, hidden through deceit and misdirection from Earth and Trisolaris alike. Three of the Wallfacers are influential statesmen and scientists, but the fourth is a total unknown. Luo Ji, an unambitious Chinese astronomer and sociologist, is baffled by his new status. All he knows is that he\'s the one Wallfacer that Trisolaris wants dead.\nNguồn: https://openlibrary.org/works/OL16314245W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/10526598-M.jpg',NULL,116000.00,91000.00,NULL,13,1,'The Dark Forest (The Three-Body Problem Series Book 2)',5,1),(100,'Isaac Asimov','LIKE_NEW','2026-10-29 23:46:44.000000','On the remote planet Solaria the first murder for two hundred years has been committed. The Solarians are Spacers with a civilisation based on robots instead of slaves - and some pretty weird taboos and phobias.\r\nInto this strange set-up comes Terran detective Elijah Baley, assigned to find the murderer and act as an investigator for his government. But as an Earthman, Baley finds aspects of life on Solaria difficult, even terrifying, to cope with. (Men on Earth live deep underground in their vast caves of steel and are terrified of anything outside.)\r\nFrom the moment of his arrival on Solaria, Baley\'s investigation becomes an ordeal of nerves under the pitiless glare of the naked sun...\nNguồn: https://openlibrary.org/works/OL46398W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6542967-M.jpg',NULL,122000.00,97000.00,NULL,3,1,'The Naked Sun',5,2),(101,'Harlan Ellison','FAIR','2026-10-29 23:46:44.000000','This is a story set in a post-apocalyptic future. The Cold War progressed until it was too complicated for humans to manage, so the three major superpowers each developed a computer program to help run the war. When one of the programs becomes sentient it eliminates all of the human race except five persons, which it tortures for eternity.\nNguồn: https://openlibrary.org/works/OL1737320W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/5540875-M.jpg',NULL,128000.00,103000.00,NULL,4,1,'I Have No Mouth and I Must Scream',5,3),(102,'Bill Bryson','GOOD','2026-10-29 23:46:44.000000','A Short History of Nearly Everything by American author Bill Bryson is a popular science book that explains some areas of science, using easily accessible language that appeals more so to the general public than many other books dedicated to the subject. It was one of the bestselling popular science books of 2005 in the United Kingdom, selling over 300,000 copies.\r\n\r\nA Short History deviates from Bryson\'s popular travel book genre, instead describing general sciences such as chemistry, paleontology, astronomy, and particle physics. In it, he explores time from the Big Bang to the discovery of quantum mechanics, via evolution and geology.\r\n\r\nBill Bryson wrote this book because he was dissatisfied with his scientific knowledge—that was, not much at all. He writes that science was a distant, unexplained subject at school. Textbooks and teachers alike did not ignite the passion for knowledge in him, mainly because they never delved in the whys, hows, and whens.\r\n\r\nThe ebook can be found elsewhere on the web at:\r\nhttp://www.huzheng.org/bookstore/AShortHistoryofNearlyEverything.pdf\nNguồn: https://openlibrary.org/works/OL74128W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/12725620-M.jpg',NULL,134000.00,109000.00,NULL,5,1,'A short history of nearly everything',5,1),(103,'Richard K. Morgan','LIKE_NEW','2026-10-29 23:46:44.000000','Chủ đề được Open Library phân loại: Science Fiction, Cyberpunk, Thriller, Life on other planets, Fiction, Fiction, science fiction, hard science fiction, Fiction, science fiction, general, Long Now Manual for Civilization.\nNguồn: https://openlibrary.org/works/OL29914687W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/13223488-M.jpg',NULL,140000.00,115000.00,NULL,6,1,'Altered Carbon',5,2),(104,'Larry Niven','FAIR','2026-10-29 23:46:44.000000','Lucifer\'s Hammer is a post-apocalyptic science fiction novel by Larry Niven and Jerry Pournelle, first published in 1977. It was nominated for the Hugo Award for Best Novel in 1978.\r\nThe story details a cometary impact on Earth, an end to civilization, and the battle for the future. It encompasses the discovery of the comet, the LA social scene, and a cast of diverse characters whom fate seems to smile upon and allow to survive the massive cataclysm and the resulting tsunamis, plagues, famines and battles amongst scavengers and cannibals.\nNguồn: https://openlibrary.org/works/OL510435W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/4414184-M.jpg',NULL,146000.00,121000.00,NULL,7,1,'Lucifer\'s Hammer',5,3),(105,'Larry Niven','GOOD','2026-10-29 23:46:44.000000','Science fiction classic about the rise, fall and subsequent rise of a civilization where the peak catastrophe is known as the \"crazy eddy point\". Introduces the concept of frictionless toilets that don\'t have any water in them but I suspect the authors didn\'t think it all the way through - I don\'t recall a negative air pressure that would keep odours in their rightfull place. Nevertheless a fascinating read.\r\nI haven\'t read this for donkeys years which is why I\'m searching for an e-copy.\nNguồn: https://openlibrary.org/works/OL15331302W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/408133-M.jpg',NULL,152000.00,127000.00,NULL,8,1,'The Mote in God\'s Eye',5,1),(106,'Frank Herbert','LIKE_NEW','2026-10-29 23:46:44.000000','Fourth book in the Dune series. Takes place 3500 years after the events of the original trilogy. Tells the story of Leto, the son of Paul Atreides, who has traded his humanity to become an immortal sandworm of Dune.\nNguồn: https://openlibrary.org/works/OL893515W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6711531-M.jpg',NULL,158000.00,133000.00,NULL,9,1,'God Emperor of Dune',5,2),(107,'Andy Weir','FAIR','2026-10-29 23:46:44.000000','Ryland Grace is the sole survivor on a desperate, last-chance mission–and if he fails, humanity and the earth itself will perish. Except that right now, he doesn’t know that. He can’t even remember his own name, let alone the nature of his assignment or how to complete it. All he knows is that he’s been asleep for a very, very long time. And he’s just been awakened to find himself millions of miles from home, with nothing but two corpses for company.\r\n\r\nHis crewmates dead, his memories fuzzily returning, he realizes that an impossible task now confronts him. Alone on this tiny ship that’s been cobbled together by every government and space agency on the planet and hurled into the depths of space, it’s up to him to conquer an extinction-level threat to our species.\r\n\r\nAnd thanks to an unexpected ally, he just might have a chance.\r\n\r\nPart scientific mystery, part dazzling interstellar journey, *Project Hail Mary* is a tale of discovery, speculation, and survival to rival *The Martian*–while taking us to places it never dreamed of going.\nNguồn: https://openlibrary.org/works/OL21745884W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/11200092-M.jpg',NULL,164000.00,139000.00,NULL,10,1,'Project Hail Mary',5,3),(108,'Isaac Asimov','GOOD','2026-10-29 23:46:44.000000','The story of temporal engineers who meta-regulate the history of humanity through the centuries, eliminating risk, adventure, and space travel in the process. One man rebels in order to save the existence of someone he loves, and in the end the time bureaucracy is destroyed for the sake of individuality and human achievement. The theme is the opposite of the Foundation stories, where the central planners and manipulators of humanity always dominate.\nNguồn: https://openlibrary.org/works/OL46108W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6622699-M.jpg',NULL,74000.00,49000.00,NULL,11,1,'The End of Eternity',5,1),(109,'Arthur C. Clarke','LIKE_NEW','2026-10-29 23:46:44.000000','A novel that proposes an idea about how the human race might have begun and where it might be headed...given a little help from out there. A colaboration of ideas with director Stanley Kubrick in the late 1960\'s it begins at \"the dawn of man\" and then leaps to the year 2001 where a mission to Saturn (Jupiter in the film) is mounted to try and answer questions raised by the discovery of an ancient artifact dug up on the moon. Though not particularly fast paced, the science is good, and there are a few hair raising events. There are also interesting speculations about the future, such as the space shuttle, and a device eerily similar to an iPad. Leaving plenty of room for contemplation and the appreciation for the inevitable trials of space travel, this is one of the truly landmark pieces of hard science fiction.\nNguồn: https://openlibrary.org/works/OL17365W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/11344400-M.jpg',NULL,80000.00,55000.00,NULL,12,1,'2001',5,2),(110,'Isaac Asimov','FAIR','2026-10-29 23:46:44.000000','Biron Farrell was young and naïve, but he was growing up fast. A radiation bomb planted in his dorm room changed him from an innocent student at the University of Earth to a marked man, fleeing desperately from an unknown assassin.\r\n\r\nHe soon discovers that, many light-years away, his father, the highly respected Rancher of Widemos, has been murdered. Stunned, grief-stricken, and outraged, Biron is determined to uncover the reasons behind his father’s death, and becomes entangled in an intricate saga of rebellion, political intrigue, and espionage.\r\n\r\nThe mystery takes him deep into space where he finds himself in a relentless struggle with the power-mad despots of Tyrann. Now it is not just a case of life or death for Biron, but a question of freedom for the galaxy.\nNguồn: https://openlibrary.org/works/OL46399W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/6565338-M.jpg',NULL,86000.00,61000.00,NULL,13,1,'The Stars, Like Dust',5,3),(111,'Robert A. Heinlein','GOOD','2026-10-29 23:46:44.000000','Engineered from the finest genes, and trained to be a secret courier in a future world, Friday operates over a near-future Earth, where chaos reigns. Working at Boss\'s whimsical behest she travels from far north to deep south, finding quick, expeditious solutions as one calamity after another threatens to explode in her face....\r\nFabulous Heinlein world of fascination and intrigue.\nNguồn: https://openlibrary.org/works/OL59706W. Giá và tồn kho là dữ liệu demo.','https://covers.openlibrary.org/b/id/14630717-M.jpg',NULL,92000.00,67000.00,NULL,3,1,'Friday',5,1);
